class MoodDriftModulator:
    def __init__(self, alpha=0.3, history_size=5):
        self.alpha = alpha  # smoothing factor for EMA
        self.history = deque(maxlen=history_size)
        self.previous = None
        self.suicidal_keywords = [
            "end it all", "kill myself", "can't go on", "worthless",
            "nothing matters", "give up", "goodbye forever", "no reason to live"
        ]

    def _is_suicidal(self, text):
        lowered = text.lower()
        return any(kw in lowered for kw in self.suicidal_keywords)

    def detect_crisis(self, user_input):
        if self._is_suicidal(user_input):
            return {
                "crisis_detected": True,
                "message": "🚨 High-risk emotional state detected. Consider triggering emergency response or calming playlist."
            }
        return {"crisis_detected": False}

    def smooth_emotion(self, current):
        if self.previous is None:
            self.previous = current
            self.history.append(current)
            return current

        smoothed = {
            key: self.alpha * current[key] + (1 - self.alpha) * self.previous[key]
            if isinstance(current[key], float)
            else current[key]
            for key in current
        }

        self.previous = smoothed
        self.history.append(smoothed)
        return smoothed

    def summarize_drift(self):
        if not self.history:
            return None
        return {
            "recent_average": {
                key: round(sum(item[key] for item in self.history) / len(self.history), 3)
                for key in self.history[0]
                if isinstance(self.history[0][key], float)
            }
        }

